"""情感咨询相关的 HTTP 接口。对外提供 4 个接口（前缀 /api/emotion）：- POST /indexes/build       构建/重建书籍向量索引- POST /threads             创建一个情感咨询会话- POST /chat/stream         流式对话（SSE），支持 RAG 检索与生成恋爱报告- GET  /reports/{id}        下载生成的恋爱报告 PDF具体业务逻辑委托给 emotion.service 中的单例 emotion_service。"""from __future__ import annotations  # 启用延迟注解求值from typing import Any  # 用于索引构建结果等动态 JSON 结构from fastapi import APIRouter, HTTPException  # 路由分组与标准 HTTP 错误响应from fastapi.responses import FileResponse, StreamingResponse  # 文件下载与 SSE 流式响应from api.schemas import EmotionBuildRequest, EmotionChatRequest  # 情感模块请求体模型from api.sse import sse  # 将事件字典格式化为 SSE 文本行from emotion.reports import find_report_file  # 按 report_id 查找已生成的 PDF 路径from emotion.service import emotion_service  # 情感咨询业务单例（RAG、对话、记忆）router = APIRouter(prefix="/api/emotion")  # 情感咨询路由组，所有接口以 /api/emotion 为前缀@router.post("/indexes/build")  # HTTP POST：构建或重建情感书籍向量索引def build_emotion_indexes(req: EmotionBuildRequest) -> dict[str, Any]:  # 路由处理函数：触发 Chroma 索引构建    """构建书籍向量索引。出错时不抛异常，而是把错误信息包进结果返回给前端。"""    try:  # 尝试调用 service 构建 Chroma 向量索引        result = emotion_service.build_indexes(req.book_name)  # book_name 为 None 时索引全部书籍    except Exception as exc:  # 捕获任意异常        result = {"book_name": req.book_name or "*", "status": "error", "error": str(exc)}  # 包装成统一错误结构    return {"result": result}  # 始终返回 200，由 result.status 区分成功/失败@router.post("/threads")  # HTTP POST：创建新的情感咨询会话def create_emotion_thread() -> dict[str, str]:  # 路由处理函数：分配 threadId 并写入 Redis 记忆键    """创建一个情感咨询会话，返回 threadId（Redis 会用它作为记忆的 key）。"""    return {"threadId": emotion_service.create_thread()}  # 委托 service 生成并注册新会话 id@router.post("/chat/stream")  # HTTP POST：SSE 流式情感咨询对话def stream_emotion_chat(req: EmotionChatRequest) -> StreamingResponse:  # 路由处理函数：RAG+LLM 流式输出    """流式情感咨询对话：把 service 产出的事件逐条包成 SSE 发送给前端。"""    if not req.threadId:  # threadId 为空无法关联 Redis 记忆        raise HTTPException(status_code=400, detail="threadId required")  # 返回 400 提示前端    def event_stream():  # 内嵌生成器：把 service 事件逐条转成 SSE 文本        """把 emotion_service.stream_chat 产出的事件字典逐条转成 SSE。"""        for event in emotion_service.stream_chat(req.threadId, req.message):  # 迭代 RAG+LLM 流式事件            yield sse(event)  # 每条事件包装为 data: {...}\n\n 格式    return StreamingResponse(event_stream(), media_type="text/event-stream")  # 声明 SSE 媒体类型@router.get("/reports/{report_id}")  # HTTP GET：按 id 下载恋爱报告 PDFdef download_emotion_report(report_id: str) -> FileResponse:  # 路由处理函数：查找磁盘 PDF 并以文件流返回    """按 report_id 查找并下载对应的恋爱报告 PDF；找不到返回 404。"""    path = find_report_file(report_id)  # 在报告目录中按 id 匹配 PDF 文件    if path is None:  # 文件不存在或 id 无效        raise HTTPException(status_code=404, detail="report not found")  # 返回 404    return FileResponse(  # 以文件流形式响应，浏览器可触发下载        path=str(path),  # 磁盘上的 PDF 绝对/相对路径        media_type="application/pdf",  # MIME 类型告知客户端这是 PDF        filename=path.name,  # Content-Disposition 中使用的下载文件名    )